    public static Path getUnitPath(int id) {
        if (id < 0 || id >= COUNT) return null;
        Path p = CACHE[id];
        if (p != null) return p;
        float[] d = DATA[id];
        if (d == null) {
            d = loadData(id);
            DATA[id] = d;
        }
        p = buildPath(d);
        CACHE[id] = p;
        return p;
    }

    private static float[] loadData(int id) {
        switch (id) {
            case BACK: return data_BACK();
            case SEARCH_REGULAR: return data_SEARCH_REGULAR();
            case SEARCH_FILLED: return data_SEARCH_FILLED();
            case HOME_REGULAR: return data_HOME_REGULAR();
            case HOME_FILLED: return data_HOME_FILLED();
            case TABS_REGULAR: return data_TABS_REGULAR();
            case TABS_FILLED: return data_TABS_FILLED();
            case MENU_REGULAR: return data_MENU_REGULAR();
            case MENU_FILLED: return data_MENU_FILLED();
            case FORWARD: return data_FORWARD();
            case BOOKMARK_STAR: return data_BOOKMARK_STAR();
            case BOOKMARK_STAR_FILLED: return data_BOOKMARK_STAR_FILLED();
            case DOWNLOAD_PAGE: return data_DOWNLOAD_PAGE();
            case RELOAD: return data_RELOAD();
            case NEW_TAB: return data_NEW_TAB();
            case INCOGNITO: return data_INCOGNITO();
            case BOOKMARKS: return data_BOOKMARKS();
            case HISTORY: return data_HISTORY();
            case DOWNLOADS: return data_DOWNLOADS();
            case EXTENSIONS: return data_EXTENSIONS();
            case SHARE: return data_SHARE();
            case FIND_IN_PAGE: return data_FIND_IN_PAGE();
            case DESKTOP_SITE: return data_DESKTOP_SITE();
            case SETTINGS: return data_SETTINGS();
            case DISMISS: return data_DISMISS();
            case ADD: return data_ADD();
            case CHEVRON_RIGHT: return data_CHEVRON_RIGHT();
            case CHECKMARK: return data_CHECKMARK();
            case LOCK: return data_LOCK();
            default: return new float[0];
        }
    }

    private static Path buildPath(float[] d) {
        Path p = new Path();
        p.setFillType(Path.FillType.WINDING);
        int i = 0;
        int n = d.length;
        while (i < n) {
            int op = (int) d[i++];
            switch (op) {
                case OP_M:
                    p.moveTo(d[i++], d[i++]);
                    break;
                case OP_L:
                    p.lineTo(d[i++], d[i++]);
                    break;
                case OP_C:
                    p.cubicTo(d[i++], d[i++], d[i++], d[i++], d[i++], d[i++]);
                    break;
                case OP_Z:
                    p.close();
                    break;
            }
        }
        return p;
    }

    /** Draws a Fluent 24dp icon centered at (cx, cy) with exact optical sizePx and fill color. */
    public static void drawCentered(Canvas canvas, int iconId, float cx, float cy, float sizePx, Paint fillPaint) {
        Path p = getUnitPath(iconId);
        if (p == null) return;
        float s = sizePx / 24.0f;
        int save = canvas.save();
        canvas.translate(cx - sizePx * 0.5f, cy - sizePx * 0.5f);
        canvas.scale(s, s);
        canvas.drawPath(p, fillPaint);
        canvas.restoreToCount(save);
    }

    /** Lightweight tinted Drawable wrapping any Fluent 24dp vector icon. */
    public static final class FluentDrawable extends Drawable {
        private final int iconId;
        private final int intrinsicPx;
        private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);

        public FluentDrawable(Context ctx, int iconId, float sizeDp, int color) {
            this.iconId = iconId;
            this.intrinsicPx = Math.round(sizeDp * ctx.getResources().getDisplayMetrics().density);
            paint.setStyle(Paint.Style.FILL);
            paint.setColor(color);
        }

        public void setColor(int color) {
            if (paint.getColor() != color) {
                paint.setColor(color);
                invalidateSelf();
            }
        }

        @Override public int getIntrinsicWidth() { return intrinsicPx; }
        @Override public int getIntrinsicHeight() { return intrinsicPx; }

        @Override
        public void draw(Canvas canvas) {
            Rect b = getBounds();
            float sz = Math.min(b.width(), b.height());
            if (sz <= 0f) sz = intrinsicPx;
            drawCentered(canvas, iconId, b.exactCenterX(), b.exactCenterY(), sz, paint);
        }

        @Override public void setAlpha(int alpha) { paint.setAlpha(alpha); invalidateSelf(); }
        @Override public void setColorFilter(ColorFilter cf) { paint.setColorFilter(cf); invalidateSelf(); }
        @Override public int getOpacity() { return PixelFormat.TRANSLUCENT; }
    }
